     "又闻太祖以柱斧戳雪，厉声说好做，此后声息渐寂。",
     "五更时分，太祖崩于万岁殿，宫中传出的是遗诏而非太子的名分。",
     "皇后命宦官王继恩召德芳入宫，王继恩却直奔晋王府，请光义入宫。",
     "光义入宫，皇后见其已至，只得称母子之命皆托于官家。",
