     "a": "因为王朝的延续靠的首先不是兵，是名分。金人把宗室成批押走，却独独漏了奉使在外的康王；张邦昌僭位三十三日，最后仍要奉玉玺还政赵氏。有了这个人，江南的州县、溃散的军队、南逃的士大夫便都有了可归之处。若康王也在城中，金人立一个楚帝、再立一个齐帝，中原未必不能久持。所谓宋室一线，说的是血脉，其实说的是一个可以奉戴的名号。",
