     "结构条件：南渡之后，宋军主力多由诸大将自行招募，韩世忠、张俊、刘光世、岳飞各拥数万，粮饷自筹，号令不一；朝廷既倚之御敌，又无由制之。金人则立伪齐刘豫于河南，专以扰宋，宋金之间多了一个缓冲的祸源。",
     "近端触发：绍兴元年，秦桧自燕京南归，自称杀监守、夺舟而回，力陈南人归南、北人归北之说。绍兴七年，刘光世罢兵权，吕祉往淮西节制其众，郦琼不服，杀吕祉，挟数万众降伪齐。",
