 "thesis": "他是个没有主张的皇帝，谁替他定策，谁就替他当家。前有韩侂胄借党禁与北伐立威，后有史弥远以杀宰相、换皇帝固位；他在位三十年，只做过一件事，就是没有阻拦任何人。",
