     "诏改明年元为庆元，大赦天下，边帅各遣使入贺。",
     "从一篇论伪学的奏章开始，朝堂上换了一整套说话的人。",
     "庆元元年，赵汝愚罢相，出知福州，台谏相继论其植党。",
