     "安丙以诛曦之功掌蜀，又渐成一方之势，朝廷不得不防。",
     "吴氏三世经营的两川兵力从此不再由一家独掌。",
     "开禧之败与吴曦之叛叠加，议和之势再不可挽。",
     "此后南宋对边将的猜防更甚，战时授权愈难。",
