     "a": "因为反抗的机关早被他一件件拆掉了。台谏是他的亲故，禁军在他手里，宫中有杨皇后做内应，外廷宰执又多是他的门生。赵竑虽为皇子，却没有自己的班底，也没有任何兵权，被一纸诏书改封郡王，只能出城。更关键的是，这件事做得极快：宁宗未崩先定策，崩后即入宫，等百官上朝时，木已成舟。制度上本该有人问一句「诏书何来」，可那时已没有人敢问。",
