     "a": "因为它已经把朝廷压缩到了最小的形态：一个皇帝、一位太后、几个宰执和一支军队。没有疆土就不必守城，没有府库就不必理财，剩下的只有名分与纪律。陆秀夫每日讲书、维持朝仪，是让百官记得自己还是臣子；张世杰结舟为营、分舟而居，是把军队的组织搬到水上。真正把它拖垮的不是元军，而是淡水、疫病与粮道——海上没有田，几十万人每天的饭都要靠岸上的人肯给。形式上它很完整，物质上它一天也离不开岸。",
